Translate the following GNU C++ code to Python 3 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++ code you have to translate:
<original_code>
#include <iostream>
#include <cstdio>
#include <cstring>
#include <queue>
#include <vector>
#include <algorithm>
#include <climits>

using namespace std;

const int MAXN = 12;
const int INF = 1000000;

int dx[4] = {-1,1,0,0};
int dy[4] = {0,0,-1,1};
int N, T;
char grid1[MAXN][MAXN], grid2[MAXN][MAXN];
int A[MAXN][MAXN];
int B[MAXN][MAXN][MAXN][MAXN];
int depth[MAXN][MAXN];

const int MAX_NETWORK_NODES = 205;

struct Edge {
	int a, b, cap, flow;
};

int n, s, t, dist[MAX_NETWORK_NODES], ptr[MAX_NETWORK_NODES], queue_arr[MAX_NETWORK_NODES];
vector<Edge> edges;
vector<int> graph[MAX_NETWORK_NODES];

void addEdge(int a, int b, int cap) {
	edges.push_back({a, b, cap, 0});
	edges.push_back({b, a, 0, 0});
	graph[a].push_back(edges.size() - 2);
	graph[b].push_back(edges.size() - 1);
}

bool bfs() {
	int qh = 0, qt = 0;
	queue_arr[qt++] = s;
	memset(dist, -1, n * sizeof(dist[0]));
	dist[s] = 0;
	while (qh < qt && dist[t] == -1) {
		int v = queue_arr[qh++];
		for (int id : graph[v]) {
			int to = edges[id].b;
			if (dist[to] == -1 && edges[id].flow < edges[id].cap) {
				queue_arr[qt++] = to;
				dist[to] = dist[v] + 1;
			}
		}
	}
	return dist[t] != -1;
}

int dfs(int v, int flow) {
	if (!flow) return 0;
	if (v == t) return flow;
	for (; ptr[v] < (int)graph[v].size(); ++ptr[v]) {
		int id = graph[v][ptr[v]];
		int to = edges[id].b;
		if (dist[to] != dist[v] + 1) continue;
		int pushed = dfs(to, min(flow, edges[id].cap - edges[id].flow));
		if (pushed) {
			edges[id].flow += pushed;
			edges[id ^ 1].flow -= pushed;
			return pushed;
		}
	}
	return 0;
}

int dinic() {
	int flow = 0;
	for (;;) {
		if (!bfs()) break;
		memset(ptr, 0, n * sizeof(ptr[0]));
		while (int pushed = dfs(s, INF))
			flow += pushed;
	}
	return flow;
}

int getId(int x, int y) {
	return x * N + y;
}

void buildNetwork() {
	s = 0;
	t = 2 * N * N + 1;
	n = 2 * N * N + 2;
	for (int i = 0; i < N; ++i)
		for (int j = 0; j < N; ++j) {
			if (grid1[i][j] > '0' && grid1[i][j] <= '9')
				addEdge(s, 1 + getId(i, j), grid1[i][j] - '0');
			if (grid2[i][j] > '0' && grid2[i][j] <= '9')
				addEdge(N * N + 1 + getId(i, j), t, grid2[i][j] - '0');
		}
	for (int x1 = 0; x1 < N; ++x1)
		for (int y1 = 0; y1 < N; ++y1)
			for (int x2 = 0; x2 < N; ++x2)
				for (int y2 = 0; y2 < N; ++y2)
					if (B[x1][y1][x2][y2])
						addEdge(1 + getId(x1, y1), N * N + 1 + getId(x2, y2), INF);
}

int main() {
	scanf("%d%d", &N, &T);
	for (int i = 0; i < N; ++i)
		scanf("%s", grid1[i]);
	getchar();
	for (int i = 0; i < N; ++i)
		scanf("%s", grid2[i]);
	for (int i = 0; i < N; ++i)
		for (int j = 0; j < N; ++j)
			A[i][j] = INF;
	queue<pair<int, int>> Q;
	for (int x = 0; x < N; ++x)
		for (int y = 0; y < N; ++y)
			if (grid1[x][y] == 'Z') {
				for (int i = 0; i < 4; ++i)
					if (x + dx[i] >= 0 && x + dx[i] < N && y + dy[i] >= 0 && y + dy[i] < N && grid1[x + dx[i]][y + dy[i]] != 'Y') {
						A[x + dx[i]][y + dy[i]] = 1;
						Q.push({x + dx[i], y + dy[i]});
					}
			}
	while (!Q.empty()) {
		int x = Q.front().first, y = Q.front().second;
		Q.pop();
		for (int i = 0; i < 4; ++i)
			if (x + dx[i] >= 0 && x + dx[i] < N && y + dy[i] >= 0 && y + dy[i] < N && grid1[x + dx[i]][y + dy[i]] != 'Y' && grid1[x + dx[i]][y + dy[i]] != 'Z' && A[x + dx[i]][y + dy[i]] == INF) {
				A[x + dx[i]][y + dy[i]] = A[x][y] + 1;
				Q.push({x + dx[i], y + dy[i]});
			}
	}
	for (int x1 = 0; x1 < N; ++x1)
		for (int y1 = 0; y1 < N; ++y1)
			for (int x2 = 0; x2 < N; ++x2)
				for (int y2 = 0; y2 < N; ++y2) {
					if (grid1[x1][y1] == 'Y' || grid1[x1][y1] == 'Z' || grid1[x2][y2] == 'Y' || grid1[x2][y2] == 'Z') {
						B[x1][y1][x2][y2] = 0;
						continue;
					}
					for (int i = 0; i < N; ++i)
						for (int j = 0; j < N; ++j)
							depth[i][j] = INF;
					queue<pair<int, int>> Q2;
					depth[x1][y1] = 0;
					Q2.push({x1, y1});
					bool found = false;
					while (!Q2.empty()) {
						int x = Q2.front().first, y = Q2.front().second;
						Q2.pop();
						if (x == x2 && y == y2) {
							found = true;
							break;
						}
						if (depth[x][y] >= T || depth[x][y] >= A[x][y])
							continue;
						for (int i = 0; i < 4; ++i) {
							int x3 = x + dx[i], y3 = y + dy[i];
							if (x3 >= 0 && x3 < N && y3 >= 0 && y3 < N && grid1[x3][y3] != 'Y' && grid1[x3][y3] != 'Z' && depth[x3][y3] == INF && depth[x][y] + 1 <= A[x3][y3]) {
								depth[x3][y3] = depth[x][y] + 1;
								Q2.push({x3, y3});
							}
						}
					}
					B[x1][y1][x2][y2] = found;
				}
	buildNetwork();
	printf("%d\n", dinic());
	return 0;
}
